/* generated: faq */
(function () {
  window.OneToneI18nBundles = window.OneToneI18nBundles || { zh: {}, en: {} };
  Object.assign(window.OneToneI18nBundles.zh, {"faqPageTitle":"帮助与排错","faqPageIntro":"先选你的症状，再按步骤操作。多数情况是按键或输入法设置问题，不是软件坏了。","faqSearchLabel":"搜索问题","faqSearchPlaceholder":"遇到什么问题了？比如：按了没反应…","faqSearchEnter":"回车","faqCardTagStart":"入门","faqCardStartTitle":"先选你的问题","faqCardStartDesc":"症状快选，一秒跳到对应排错步骤。","faqCardTagKeys":"按键","faqCardKeysTitle":"按键与方案","faqCardKeysDesc":"录键失败、冲突、监听暂停，都在这里。","faqCardTagCamera":"摄像头","faqCardCameraTitle":"摄像头触发","faqCardCameraDesc":"眨眼、摇头也能当触发，画面只在本机。","faqCardTagFix":"排错","faqCardFixTitle":"提示对照与重置","faqCardFixDesc":"看不懂报错？对照表 + 重置路径在这里。","faqNavGroupStart":"快速入门","faqNavSymptoms":"先选你的问题","faqNavInstall":"下载与安装","faqNavGroupVoice":"语音","faqNavVoice":"语音与麦克风","faqNavImeWake":"输入法没唤醒","faqNavIme":"输入法预设","faqNavGroupKeys":"按键","faqNavKeys":"按键与方案","faqNavNoResponse":"按了没反应","faqNavPaused":"监听已暂停","faqNavGroupCamera":"摄像头","faqNavCamera":"摄像头触发","faqNavGroupSoftPad":"SoftPad","faqNavSoftPad":"虚拟小键盘","faqNavGroupFix":"排错","faqNavErrors":"软件提示对照","faqNavReset":"重置与反馈","faqDocsH1":"帮助中心","faqDocsLead":"按症状找入口，或用上方搜索。下面按「语音 / 按键 / 摄像头 / SoftPad」分组，旧链接锚点仍然有效。","faqTipTitle":"多数不是软件坏了","faqTipBody":"先确认托盘里一声在跑、触发键录对、输入法快捷键在记事本里能单独唤醒听写。","faqSymptomsTitle":"先选你的问题","faqSymNoResponse":"按了没反应","faqSymNoResponseHint":"触发键是否生效","faqSymImeWake":"输入法没唤醒","faqSymImeWakeHint":"语音条不出现","faqSymRecordFail":"录键失败","faqSymRecordFailHint":"未能识别该按键","faqSymWrongKeys":"按键设错了","faqSymWrongKeysHint":"怎么改回来","faqSymNoMic":"找不到麦克风","faqSymNoMicHint":"权限与设备","faqSymConflict":"按键冲突","faqSymConflictHint":"方案被自动关掉","faqSymErrors":"软件提示","faqSymErrorsHint":"看到报错怎么办","faqSymSmartScreen":"安装被拦截","faqSymSmartScreenHint":"SmartScreen 提示","faqSectionVoice":"语音与麦克风","faqQ2":"为什么检测不到麦克风？","faqMic1":"Windows：设置 → 隐私 → 麦克风 → 允许桌面应用访问。","faqMic2":"OneTone：设置 → 语音 → 刷新设备列表。","faqMic3":"硬件：USB 麦克风重插；蓝牙麦在系统声音设置里设为默认输入。","faqMic4":"区分场景：一声语音唤起与输入法听写都需要麦——若按键能唤醒输入法但无声音，多半是输入法没拿到麦克风权限。","faqMicNote":"先在 Windows「声音」里试麦，再在输入法里试听写，最后才测一声。","faqRelatedMic":"相关：<a href=\"#system-audio\">录到电脑声音</a>","faqQ3":"为什么会录到电脑声音？","faqSystemAudioBody":"在设置 → 声音 开启「录音时自动降低系统声音」。在 Windows 声音设置里禁用「立体声混音」类录音设备。优先使用耳机麦克风，避免扬声器回授。","faqQVoiceWake":"说了唤醒词没反应？","faqVoiceWake1":"确认已在设置 → 语音 开启语音唤起（轻量或离线模式）。","faqVoiceWake2":"唤醒词需与设置里勾选的短语一致，尽量在安静环境清晰说出。","faqVoiceWake3":"轻量模式依赖 Windows 语音识别，需已安装中文语音包。","faqVoiceWake4":"刚结束上一轮听写时，需等几秒再说唤醒词。","faqRelatedVoiceWake":"相关：<a href=\"#no-mic\">麦克风问题</a>","faqQImeWake":"触发有反应，但输入法没被唤醒？","faqImeWakeLead":"说明一声收到了触发，但模拟的语音快捷键不对，或输入法未就绪。","faqImeWake1":"在输入法设置里确认「语音输入 / 听写」的快捷键（如 RAlt、Ctrl+Shift 等）。","faqImeWake2":"在 OneTone 设置 → 按键，重新录入同一组合，或点输入法预设自动填入。","faqImeWake3":"录快捷键前先退出听写状态；在普通英文输入状态下录制。","faqImeWake4":"在记事本里不用一声，手动按该快捷键，确认语音条会出现。","faqRelatedImeWake":"相关：<a href=\"#wrong-keys\">改语音快捷键</a> · <a href=\"quickstart.html#step2\">上手步骤二</a>","faqSectionIme":"输入法","faqQ4":"百度输入法怎么设置快捷键？","faqBaiduBody":"在百度输入法设置里查找语音快捷键（常见 Alt+A，部分版本为 F2/F1）。在 OneTone 设置 → 按键录入同一组合，或选择百度预设。","faqQ5":"微信 / 搜狗输入法可以用吗？","faqOtherImeBody":"可以。在对应输入法里确认语音快捷键，在 OneTone 设置 → 按键录入同一组合，或点选输入法预设。","faqSectionKeys":"按键与方案","faqQ1":"为什么我按了没反应？","faqTriage1":"软件有没有开","faqTriage1Hint":"看系统托盘，一声图标要在运行","faqTriage2":"按键有没有录对","faqTriage2Hint":"设置里「你的键」和测试时按的是同一个吗？","faqTriage3":"输入法快捷键对不对","faqTriage3Hint":"在记事本直接按输入法的激活键测试","faqCheckApp":"软件在运行吗？看托盘「一声」图标；若显示「监听已暂停」，点首页恢复监听。","faqCheckKey":"键录对了吗？设置 → 按键，点「测试发送」或在记事本按同一触发键。","faqCheckShortcut":"输入法激活键能用吗？不用一声，在记事本直接按你录的语音快捷键，看是否出现语音条。","faqCheckStill":"仍无效：设置 → 运行状态查看最近按键；先在记事本测试，避开全屏游戏。","faqRelatedNoResponse":"相关：<a href=\"quickstart.html#step3\">试一次完整流程</a> · <a href=\"#listening-paused\">监听暂停</a> · <a href=\"#ime-not-wake\">输入法未唤醒</a>","faqQPaused":"顶部显示「监听已暂停」？","faqPausedBody":"暂停时所有触发键都不会响应。在首页点「恢复监听」，或从托盘菜单恢复。若正在录键，先结束录制再测试。","faqRelatedPaused":"相关：<a href=\"#no-response\">按了没反应</a>","faqQUsageScenes":"「使用场景」和列表里点选有什么区别？","faqUsageScenesLead":"一声用「当前场景」决定语音唤醒、结束词和按键提示；在列表里点一条只是浏览编辑，不会自动切换运行时。","faqUsageScenes1":"设置 → 使用场景：左侧点选场景可改按键、语音覆盖、目标应用。","faqUsageScenes2":"要让语音和 Coach 提示跟着变，需点 设为当前场景（或首页方案切换器）。","faqUsageScenes3":"全局麦克风、引擎、默认唤醒词在 全局语音；单场景可在「语音」Tab 做稀疏覆盖。","faqRelatedUsageScenes":"相关：<a href=\"quickstart.html\">上手指南</a> · <a href=\"changelog.html\">更新日志</a>","faqQWrongKeys":"按键设错了，怎么改回来？","faqWrongKeysLead":"从轻到重，按需选择：","faqWrongKeys1":"只录错一个：设置 → 按键 → 重新点「录触发键」或「录语音快捷键」。","faqWrongKeys2":"多套方案搞混：只启用一个方案；或设置 → 恢复与维护 → 回收站恢复旧方案。","faqWrongKeys3":"全部重来：设置 → 恢复与维护 →「清除全部映射」。","faqWrongKeys4":"仍异常：退出一声，删除 <code>%APPDATA%\\oneTone\\app\\config\\settings.json</code> 后重启（更新不会自动覆盖此文件）。","faqRelatedWrongKeys":"相关：<a href=\"#record-failed\">录键失败</a> · <a href=\"#reset\">恢复全部默认</a>","faqQRecordFail":"录键失败 / 提示「未能识别该按键」？","faqRecordFailLead":"这是录制被拒绝，不代表键盘坏了。常见原因与处理：","faqRecordFail1":"换一颗键：音量键、鼠标侧键、F 区单键通常最稳。","faqRecordFail2":"录触发键时不要点桌面、开始菜单；避免只按 Ctrl/Alt/Shift 等修饰键。","faqRecordFail3":"组合键：先按住修饰键，再按主键，等界面显示完整组合后松开。","faqRecordFail4":"录语音快捷键前，先退出输入法的听写状态。","faqRecordFail5":"仍失败：重启一声；少数外设需先打开该外设配套软件。","faqRelatedRecordFail":"相关：<a href=\"#error-messages\">软件提示对照</a>","faqQConflict":"提示按键冲突 / 方案被自动关掉？","faqConflictBody":"两个已启用方案使用了相同触发键（或相同外设物理键）时，一声会停用其中一个，避免乱触发。处理：只保留一个启用的方案，或给不同方案换不同的触发键。顶部「冲突」提示可点进方案列表查看。","faqRelatedConflict":"相关：<a href=\"#wrong-keys\">改触发键</a>","faqQTestFail":"测试发送失败，但实际按键好像有反应？","faqTestFail1":"测试前先点开记事本或聊天框，让光标在输入位置。","faqTestFail2":"确认未暂停监听，且未处于录键状态。","faqTestFail3":"若测试成功但外设不触发，检查触发模式是否为「长按」——轻按无效，需按住约 0.5 秒。","faqRelatedTestFail":"相关：<a href=\"#no-response\">按了没反应</a>","faqSectionCamera":"摄像头","faqCameraCardTitle":"去「摄像头」页看演示","faqCameraCardDesc":"眨眼、摇头就能触发；画面只在本机处理，不上传。详细交互与隐私说明在视觉页。","faqSectionSoftPad":"SoftPad","faqSoftPadCardTitle":"去 SoftPad 页看虚拟小键盘","faqSoftPadCardDesc":"屏幕上的小键盘、口令触发、数字键联动。用法与演示在 SoftPad 页。","faqSectionErrors":"软件提示对照","faqQErrors":"看到提示不知道什么意思？","faqErrColPrompt":"提示","faqErrColMeaning":"含义","faqErrColFix":"怎么办","faqErrWhitelist":"未能识别该按键","faqErrWhitelistMean":"录键被拒绝","faqErrWhitelistFix":"见 <a href=\"#record-failed\">录键失败</a>","faqErrPaused":"监听已暂停","faqErrPausedMean":"全局不响应触发","faqErrPausedFix":"见 <a href=\"#listening-paused\">恢复监听</a>","faqErrConflict":"按键冲突","faqErrConflictMean":"两方案抢同一键","faqErrConflictFix":"见 <a href=\"#key-conflict\">按键冲突</a>","faqErrSendFail":"测试发送失败","faqErrSendFailMean":"快捷键未送到前台","faqErrSendFailFix":"见 <a href=\"#test-send-failed\">测试发送</a>","faqErrRecording":"正在录制…","faqErrRecordingMean":"录键模式占用","faqErrRecordingFix":"先点取消录制，再测试。","faqSectionReset":"重置与反馈","faqQ6":"怎么恢复全部默认设置？","faqResetBody":"设置 → 恢复与维护 →「清除全部映射」。或退出软件后删除 <code>%APPDATA%\\oneTone\\app\\config\\settings.json</code> 再打开（应用更新不会覆盖该文件）。","faqRelatedReset":"相关：<a href=\"#wrong-keys\">只改按键、不清全部</a>","faqQ7":"还是不行，怎么反馈问题？","faqReportBody":"请附上 Windows 版本、一声版本、触发键与语音快捷键、输入法名称、复现步骤。可在设置 → 运行状态导出日志。<a href=\"https://github.com/psterman/onetone/issues/new?template=bug_report.yml\">提交问题</a>","faqNext":"还没装好？","faqNextQuickstart":"看上手指南","faqNextLink":"提交问题","faqTocTitle":"本页大纲","faqModalSearchPlaceholder":"搜索文档、症状或错误提示…","faqTeaserTitle":"遇到问题？","faq1":"为什么我按了没反应？","faq2":"为什么检测不到麦克风？","faq3":"为什么会录到电脑声音？","faqViewAll":"查看全部常见问题","faqSectionUse":"使用卡住"});
  Object.assign(window.OneToneI18nBundles.en, {"faqPageTitle":"Help & troubleshooting","faqPageIntro":"Pick your symptom first, then follow the steps. Most issues are key or IME settings—not a broken app.","faqSearchLabel":"Search","faqSearchPlaceholder":"What's wrong? e.g. key does nothing…","faqSearchEnter":"Enter","faqCardTagStart":"Start","faqCardStartTitle":"Pick your issue","faqCardStartDesc":"Symptom shortcuts jump to the matching steps.","faqCardTagKeys":"Keys","faqCardKeysTitle":"Keys & profiles","faqCardKeysDesc":"Record failures, conflicts, paused listening.","faqCardTagCamera":"Camera","faqCardCameraTitle":"Camera triggers","faqCardCameraDesc":"Blink or nod to trigger—video stays on-device.","faqCardTagFix":"Fix","faqCardFixTitle":"Messages & reset","faqCardFixDesc":"Error table and reset paths live here.","faqNavGroupStart":"Get started","faqNavSymptoms":"Pick your issue","faqNavInstall":"Download & install","faqNavGroupVoice":"Voice","faqNavVoice":"Voice & microphone","faqNavImeWake":"IME won't wake","faqNavIme":"IME presets","faqNavGroupKeys":"Keys","faqNavKeys":"Keys & profiles","faqNavNoResponse":"Key does nothing","faqNavPaused":"Listening paused","faqNavGroupCamera":"Camera","faqNavCamera":"Camera triggers","faqNavGroupSoftPad":"SoftPad","faqNavSoftPad":"On-screen pad","faqNavGroupFix":"Fix","faqNavErrors":"Message reference","faqNavReset":"Reset & report","faqDocsH1":"Help center","faqDocsLead":"Jump by symptom or search above. Sections follow Voice / Keys / Camera / SoftPad. Old deep-link anchors still work.","faqTipTitle":"Usually not a broken app","faqTipBody":"First check the tray icon is running, the trigger key is recorded correctly, and the IME shortcut wakes dictation in Notepad alone.","faqSymptomsTitle":"Pick your issue","faqSymNoResponse":"Key does nothing","faqSymNoResponseHint":"Trigger not firing","faqSymImeWake":"IME won't wake","faqSymImeWakeHint":"No voice bar","faqSymRecordFail":"Recording failed","faqSymRecordFailHint":"Key not recognized","faqSymWrongKeys":"Wrong keys set","faqSymWrongKeysHint":"How to fix","faqSymNoMic":"No microphone","faqSymNoMicHint":"Permission & device","faqSymConflict":"Key conflict","faqSymConflictHint":"Profile auto-disabled","faqSymErrors":"App messages","faqSymErrorsHint":"What they mean","faqSymSmartScreen":"Install blocked","faqSymSmartScreenHint":"SmartScreen prompt","faqSectionVoice":"Voice & microphone","faqQ2":"Why can't it detect my microphone?","faqMic1":"Windows: Settings → Privacy → Microphone → allow desktop apps.","faqMic2":"OneTone: Settings → Voice → refresh device list.","faqMic3":"Hardware: replug USB mic; set Bluetooth mic as default input in Sound settings.","faqMic4":"Voice wake and IME dictation both need a mic — if keys wake the IME but there's no audio, the IME likely lacks mic permission.","faqMicNote":"Test the mic in Windows Sound first, then in your IME, then OneTone.","faqRelatedMic":"Related: <a href=\"#system-audio\">Picks up system audio</a>","faqQ3":"Why does it pick up system audio?","faqSystemAudioBody":"Enable lower system volume while recording in Settings → Sounds. Disable Stereo Mix in Windows Sound. Prefer a headset mic to avoid speaker bleed.","faqQVoiceWake":"Wake phrase doesn't work?","faqVoiceWake1":"Enable voice wake in Settings → Voice (Light or Offline mode).","faqVoiceWake2":"Phrase must match what's selected in settings; speak clearly in a quiet room.","faqVoiceWake3":"Light mode needs Windows speech recognition and a Chinese language pack.","faqVoiceWake4":"Wait a few seconds after ending dictation before saying the wake phrase again.","faqRelatedVoiceWake":"Related: <a href=\"#no-mic\">Microphone issues</a>","faqQImeWake":"Trigger works but IME doesn't wake?","faqImeWakeLead":"OneTone received the trigger, but the simulated voice shortcut is wrong or the IME isn't ready.","faqImeWake1":"In your IME settings, confirm the voice/dictation shortcut (e.g. RAlt, Ctrl+Shift).","faqImeWake2":"In OneTone Settings → Keys, re-record the same combo or pick an IME preset.","faqImeWake3":"Exit dictation before recording the shortcut; record in normal typing mode.","faqImeWake4":"In Notepad without OneTone, press that shortcut and confirm the voice bar appears.","faqRelatedImeWake":"Related: <a href=\"#wrong-keys\">Fix voice shortcut</a> · <a href=\"quickstart.html#step2\">Step 2</a>","faqSectionIme":"Input methods","faqQ4":"How do I set up Baidu IME shortcuts?","faqBaiduBody":"Find Baidu's voice shortcut in its settings (often Alt+A; F2/F1 on some builds). Record the same combo in OneTone Settings → Keys, or pick the Baidu preset.","faqQ5":"Can I use WeChat or Sogou IME?","faqOtherImeBody":"Yes. Confirm the voice shortcut in your IME, then record the same combo in OneTone Settings → Keys, or pick a preset.","faqSectionKeys":"Keys & profiles","faqQ1":"Why doesn't my key do anything?","faqTriage1":"Is the app running?","faqTriage1Hint":"Check the system tray for the OneTone icon","faqTriage2":"Is the key recorded correctly?","faqTriage2Hint":"Same key in Settings and when you test?","faqTriage3":"Is the voice shortcut correct?","faqTriage3Hint":"In Notepad, press the IME activation key directly","faqCheckApp":"Is the app running? Check the tray icon; if listening is paused, resume from the home screen.","faqCheckKey":"Key correct? Settings → Keys — use Test Send or press the same trigger in Notepad.","faqCheckShortcut":"Does the IME shortcut work? Without OneTone, press your voice shortcut in Notepad and confirm the voice bar appears.","faqCheckStill":"Still stuck: Settings → Runtime for recent keys; test in Notepad first; avoid fullscreen games.","faqRelatedNoResponse":"Related: <a href=\"quickstart.html#step3\">Try the full flow</a> · <a href=\"#listening-paused\">Listening paused</a> · <a href=\"#ime-not-wake\">IME not waking</a>","faqQPaused":"「Listening paused」at the top?","faqPausedBody":"While paused, no triggers fire. Resume from the home screen or tray menu. Finish recording mode before testing.","faqRelatedPaused":"Related: <a href=\"#no-response\">Key does nothing</a>","faqQUsageScenes":"Usage scenes vs. clicking a row in the list?","faqUsageScenesLead":"OneTone uses the active scene for wake/end phrases and key hints. Clicking a row only selects it for editing — runtime does not switch until you activate it.","faqUsageScenes1":"Settings → Usage scenes: pick a scene to edit keys, voice overrides, and app targets.","faqUsageScenes2":"To change wake phrases and Coach HUD, press Set as current scene (or use the home switcher).","faqUsageScenes3":"Mic, engine, and default wake phrases live under Global voice; per-scene sparse overrides are on the Voice tab.","faqRelatedUsageScenes":"Related: <a href=\"quickstart.html\">Quickstart</a> · <a href=\"changelog.html\">Changelog</a>","faqQWrongKeys":"Wrong keys — how do I fix them?","faqWrongKeysLead":"Lightest fix first:","faqWrongKeys1":"One key wrong: Settings → Keys → re-record trigger or voice shortcut.","faqWrongKeys2":"Mixed profiles: enable only one; or Settings → Recovery → Trash to restore an old profile.","faqWrongKeys3":"Start over: Settings → Recovery → Clear all mappings.","faqWrongKeys4":"Still broken: quit OneTone, delete <code>%APPDATA%\\oneTone\\app\\config\\settings.json</code>, restart (updates won't overwrite it).","faqRelatedWrongKeys":"Related: <a href=\"#record-failed\">Recording failed</a> · <a href=\"#reset\">Full reset</a>","faqQRecordFail":"Recording failed / 「Could not recognize that key」?","faqRecordFailLead":"Recording was rejected — your keyboard is probably fine.","faqRecordFail1":"Try another key: volume keys, mouse side button, or an F-key often work best.","faqRecordFail2":"Don't click the desktop or Start menu while recording; avoid modifier-only presses.","faqRecordFail3":"For combos: hold modifiers, press the main key, wait for the full combo to show.","faqRecordFail4":"Exit IME dictation before recording the voice shortcut.","faqRecordFail5":"Still failing: restart OneTone; some peripherals need their vendor software running.","faqRelatedRecordFail":"Related: <a href=\"#error-messages\">Message reference</a>","faqQConflict":"Key conflict / profile auto-disabled?","faqConflictBody":"Two enabled profiles share the same trigger (or physical key). OneTone disables one to avoid double-firing. Keep one profile enabled or use different triggers. Tap the conflict badge on the home screen for details.","faqRelatedConflict":"Related: <a href=\"#wrong-keys\">Change trigger key</a>","faqQTestFail":"Test send failed but the key seems to work?","faqTestFail1":"Open Notepad or a chat box and place the cursor before testing.","faqTestFail2":"Confirm listening isn't paused and you're not in record mode.","faqTestFail3":"If test works but the peripheral doesn't, check trigger mode — Long press needs ~0.5s hold, not a tap.","faqRelatedTestFail":"Related: <a href=\"#no-response\">Key does nothing</a>","faqSectionCamera":"Camera","faqCameraCardTitle":"See the Camera page demo","faqCameraCardDesc":"Blink or nod to trigger; video stays local. Full demo and privacy notes are on the Camera page.","faqSectionSoftPad":"SoftPad","faqSoftPadCardTitle":"See the SoftPad page","faqSoftPadCardDesc":"On-screen numpad, voice aliases, and key sync—demos live on SoftPad.","faqSectionErrors":"Message reference","faqQErrors":"What does this message mean?","faqErrColPrompt":"Message","faqErrColMeaning":"Meaning","faqErrColFix":"What to do","faqErrWhitelist":"Could not recognize that key","faqErrWhitelistMean":"Recording rejected","faqErrWhitelistFix":"See <a href=\"#record-failed\">Recording failed</a>","faqErrPaused":"Listening paused","faqErrPausedMean":"Triggers ignored globally","faqErrPausedFix":"See <a href=\"#listening-paused\">Resume listening</a>","faqErrConflict":"Key conflict","faqErrConflictMean":"Two profiles, one key","faqErrConflictFix":"See <a href=\"#key-conflict\">Key conflict</a>","faqErrSendFail":"Test send failed","faqErrSendFailMean":"Shortcut didn't reach foreground","faqErrSendFailFix":"See <a href=\"#test-send-failed\">Test send</a>","faqErrRecording":"Recording…","faqErrRecordingMean":"Record mode active","faqErrRecordingFix":"Cancel recording first, then test.","faqSectionReset":"Reset & report","faqQ6":"How do I reset everything?","faqResetBody":"Settings → Recovery → Clear all mappings. Or quit and delete <code>%APPDATA%\\oneTone\\app\\config\\settings.json</code> (updates preserve this file).","faqRelatedReset":"Related: <a href=\"#wrong-keys\">Fix keys without full reset</a>","faqQ7":"Still stuck — how do I report an issue?","faqReportBody":"Include Windows version, OneTone version, trigger & voice shortcuts, IME name, and steps to reproduce. Export logs from Settings → Runtime. <a href=\"https://github.com/psterman/onetone/issues/new?template=bug_report.yml\">Report issue</a>","faqNext":"Not installed yet?","faqNextQuickstart":"Get started guide","faqNextLink":"Report issue","faqTocTitle":"On this page","faqModalSearchPlaceholder":"Search docs, symptoms, or error messages…","faqTeaserTitle":"Having trouble?","faq1":"Why doesn't my key do anything?","faq2":"Why can't it detect my microphone?","faq3":"Why does it pick up system audio?","faqViewAll":"View all FAQ","faqSectionUse":"Stuck while using"});
})();
